class Trader:
    def run(self, state: TradingState) -> Tuple[Dict[Symbol, List[Order]], int, str]:
        result: Dict[Symbol, List[Order]] = {}
        conversions = 0
        td = json.loads(state.traderData) if state.traderData else {}

        mids_hist: Dict[str, List[float]] = td.get("mids", {})
        mpdev_hist: Dict[str, List[float]] = td.get("mpdev", {})
        ret1_hist: Dict[str, List[float]] = td.get("ret1", {})
        flow_hist: Dict[str, List[float]] = td.get("flow", {})

        bb: Dict[str, int] = {}
        ba: Dict[str, int] = {}
        mids: Dict[str, float] = {}
        for sym in FAMILY_PRODUCTS:
            if sym not in state.order_depths:
                continue
            od = state.order_depths[sym]
            if not od.buy_orders or not od.sell_orders:
                continue
            bb[sym] = max(od.buy_orders.keys())
            ba[sym] = min(od.sell_orders.keys())
            mids[sym] = (bb[sym] + ba[sym]) / 2.0

        # Update per-symbol mid + microprice_dev + ret_1 buffers BEFORE feature compute.
        for sym in FAMILY_PRODUCTS:
            if sym not in mids:
                continue
            mid = mids[sym]
            hist = mids_hist.get(sym, [])
            if hist:
                ret_1 = mid - hist[-1]
            else:
                ret_1 = 0.0
            hist.append(mid)
            if len(hist) > MID_BUFFER_LEN:
                hist = hist[-MID_BUFFER_LEN:]
            mids_hist[sym] = hist

            r1seq = ret1_hist.get(sym, [])
            r1seq.append(ret_1)
            if len(r1seq) > RET1_BUFFER_LEN:
                r1seq = r1seq[-RET1_BUFFER_LEN:]
            ret1_hist[sym] = r1seq

            mp_dev_now = _microprice_dev(state.order_depths[sym], mid)
            mp_seq = mpdev_hist.get(sym, [])
            mp_seq.append(mp_dev_now)
            if len(mp_seq) > MPDEV_BUFFER_LEN:
                mp_seq = mp_seq[-MPDEV_BUFFER_LEN:]
            mpdev_hist[sym] = mp_seq

        # Family-mean microprice_dev_lag5 (one scalar per tick across the family).
        lag5_vals = []
        for sym in FAMILY_PRODUCTS:
            seq = mpdev_hist.get(sym, [])
            if len(seq) >= 6:
                lag5_vals.append(seq[-6])
        fam_mpdev_lag5 = sum(lag5_vals) / len(lag5_vals) if lag5_vals else 0.0

        for sym in PRODUCT_TARGETS:
            if sym not in mids:
                continue
            mids_local = mids_hist.get(sym, [])
            if len(mids_local) < WARMUP_TICKS:
                continue

            market_trades = state.market_trades.get(sym, [])
            feats = compute_features(
                sym, state.order_depths[sym], bb[sym], ba[sym], mids[sym],
                mids_hist, mpdev_hist, ret1_hist, flow_hist,
                market_trades, fam_mpdev_lag5,
            )
            edge_raw = predict_edge(feats)
            edge = edge_raw * LIVE_HAIRCUT

            spread = float(ba[sym] - bb[sym])
            half_sp = 0.5 * spread
            threshold = half_sp + ENTRY_BUFFER

            pos = state.position.get(sym, 0)
            orders: List[Order] = []
            if edge > threshold and pos < POSITION_LIMIT:
                qty = min(BASE_QTY, POSITION_LIMIT - pos)
                if qty > 0:
                    orders.append(Order(sym, ba[sym], +qty))
            elif edge < -threshold and pos > -POSITION_LIMIT:
                qty = min(BASE_QTY, POSITION_LIMIT + pos)
                if qty > 0:
                    orders.append(Order(sym, bb[sym], -qty))

            if orders:
                result[sym] = orders

        td["mids"] = mids_hist
        td["mpdev"] = mpdev_hist
        td["ret1"] = ret1_hist
        td["flow"] = flow_hist
        s = json.dumps(td)
        logger.flush(state, result, conversions, s)
        return result, conversions, s
